# Ask for a door from 1 to 3
while True:
    reply = input("Door? ")
    try:
        door = int(reply)
    except ValueError:
        print("Type a number.")
        continue
    if 1 <= door <= 3:
        break
    print("There are only 3 doors.")
print("You open door", door)

