tries = 0
while True:
    tries += 1
    reply = input("Travellers? ")
    if not reply.lstrip("-").isdigit():
        print("not a number")
    elif not 1 <= int(reply) <= 8:
        print("from 1 to 8 only")
    else:
        break
print(tries)
print(int(reply))

tries = 0
travellers = None
while travellers is None:
    tries = tries + 1
    try:
        number = int(input("Travellers? "))
    except ValueError:
        print("not a number")
    else:
        if 1 <= number <= 8:
            travellers = number
        else:
            print("from 1 to 8 only")
print(tries)
print(travellers)
